   745  /* Append a data buffer to a super-chunk. */
   746  int blosc2_schunk_append_buffer(blosc2_schunk *schunk, void *src, int32_t nbytes) {
   747    uint8_t* chunk = malloc(nbytes + BLOSC_MAX_OVERHEAD);
   748    /* Compress the src buffer using super-chunk context */
   749    int cbytes = blosc2_compress_ctx(schunk->cctx, src, nbytes, chunk,
   750                                     nbytes + BLOSC_MAX_OVERHEAD);
   751    if (cbytes < 0) {
   752      free(chunk);
   753      return cbytes;
   754    }
   755    // We don't need a copy of the chunk, as it will be shrinked if necessary
   756    int nchunks = blosc2_schunk_append_chunk(schunk, chunk, false);
   757    if (nchunks < 0) {
   758      BLOSC_TRACE_ERROR("Error appending a buffer in super-chunk");
   759      return nchunks;
   760    }
   761
   762    return nchunks;
   763  }
