   765  /* Decompress and return a chunk that is part of a super-chunk. */
   766  int blosc2_schunk_decompress_chunk(blosc2_schunk *schunk, int nchunk,
   767                                     void *dest, int32_t nbytes) {
   768    int32_t chunk_nbytes;
   769    int32_t chunk_cbytes;
   770    int chunksize;
   771    int rc;
   772    blosc2_frame_s* frame = (blosc2_frame_s*)schunk->frame;
   773
   774    if (frame == NULL) {
   775      if (nchunk >= schunk->nchunks) {
   776        BLOSC_TRACE_ERROR("nchunk ('%d') exceeds the number of chunks "
   777                          "('%d') in super-chunk.", nchunk, schunk->nchunks);
   778        return BLOSC2_ERROR_INVALID_PARAM;
   779      }
   780      uint8_t* src = schunk->data[nchunk];
   781      if (src == 0) {
   782        return 0;
   783      }
   784
   785      rc = blosc2_cbuffer_sizes(src, &chunk_nbytes, &chunk_cbytes, NULL);
   786      if (rc < 0) {
   787        return rc;
   788      }
   789
   790      if (nbytes < chunk_nbytes) {
   791        BLOSC_TRACE_ERROR("Buffer size is too small for the decompressed buffer "
   792                          "('%d' bytes, but '%d' are needed).", nbytes, chunk_nbytes);
   793        return BLOSC2_ERROR_INVALID_PARAM;
   794      }
   795
   796      chunksize = blosc2_decompress_ctx(schunk->dctx, src, chunk_cbytes, dest, nbytes);
   797      if (chunksize < 0 || chunksize != chunk_nbytes) {
   798        BLOSC_TRACE_ERROR("Error in decompressing chunk.");
   799        if (chunksize < 0)
   800          return chunksize;
   801        return BLOSC2_ERROR_FAILURE;
   802      }
   803    } else {
   804      chunksize = frame_decompress_chunk(schunk->dctx, frame, nchunk, dest, nbytes);
   805      if (chunksize < 0) {
   806        return chunksize;
   807      }
   808    }
   809    return chunksize;
   810  }
